export const dictionaries: Record<LocaleCode, Dictionary> = { es, en, pt, fr, de };
export const localeTags: Record<LocaleCode, string> = { es: 'es', en: 'en', pt: 'pt-BR', fr: 'fr', de: 'de' };
export const languageOptions: Array<{ code: LocaleCode; label: string; short: string }> = [
  { code: 'es', label: 'Español', short: 'ES' },
  { code: 'en', label: 'English', short: 'EN' },
  { code: 'pt', label: 'Português', short: 'PT' },
  { code: 'fr', label: 'Français', short: 'FR' },
  { code: 'de', label: 'Deutsch', short: 'DE' },
];

export const resolveLocale = (saved: string | null, browserLanguage: string): LocaleCode => {
  if (saved === 'es' || saved === 'en' || saved === 'pt' || saved === 'fr' || saved === 'de') return saved;
  const language = browserLanguage.toLowerCase();
  if (language.startsWith('fr')) return 'fr';
  if (language.startsWith('pt')) return 'pt';
  if (language.startsWith('en')) return 'en';
  if (language.startsWith('de')) return 'de';
  return 'es';
};

const detectLanguage = (): LocaleCode => resolveLocale(localStorage.getItem(STORAGE_KEY), navigator.language);

type Variables = Record<string, string | number>;
const format = (message: string, variables?: Variables) => variables
  ? message.replace(/\{(\w+)\}/g, (match, key: string) => String(variables[key] ?? match))
  : message;

interface I18nValue {
  language: LocaleCode;
  locale: string;
  setLanguage: (language: LocaleCode) => void;
  t: (key: MessageKey, variables?: Variables) => string;
}

const I18nContext = createContext<I18nValue | null>(null);

export function I18nProvider({ children }: { children: ReactNode }) {
  const [language, setLanguageState] = useState<LocaleCode>(detectLanguage);
  const setLanguage = (next: LocaleCode) => {
    localStorage.setItem(STORAGE_KEY, next);
    setLanguageState(next);
  };
  const value = useMemo<I18nValue>(() => ({
    language,
    locale: localeTags[language],
    setLanguage,
    t: (key, variables) => format(dictionaries[language][key] || es[key], variables),
  }), [language]);

  useEffect(() => {
    document.documentElement.lang = localeTags[language];
    document.title = dictionaries[language]['app.name'];
    document.querySelector('meta[name="description"]')?.setAttribute('content', dictionaries[language]['app.description']);
  }, [language]);

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

export const useI18n = (): I18nValue => {
  const value = useContext(I18nContext);
  if (!value) throw new Error('useI18n must be used inside I18nProvider');
  return value;
};
